// The Demos tab's catalogue: step-by-step cases a visitor clicks through.
//
// demoCatalog.json is GENERATED by scripts/build_demos.py, never edited by hand. Each case's
// first step is a GIS harness task's own question on that task's own pinned data, so what a
// demo shows is what the harness measures, and `reliability` says how often it has worked.
// Later steps are follow-ups that put the result on the map.
import catalogue from './demoCatalog.json';

export interface DemoFile { name: string; path: string; bytes: number }
export interface DemoStep { label: string; prompt: string }
export interface DemoCase {
  id: string;
  title: string;
  blurb: string;
  tags: string[];
  /** The kind of spatial analysis the case is mainly about (one of DEMO_CATEGORIES). */
  category: string;
  harnessTask: string;
  reliability: string;
  files: DemoFile[];
  steps: DemoStep[];
}

export const DEMOS: DemoCase[] = catalogue as DemoCase[];

// The panel's groups: Longley, Goodchild et al.'s types of spatial analysis. Each case sits under
// its main type; the others it touches are in its tags. Hypothesis testing leads because it holds
// the Chicago case, the fullest demo (join, rates, Moran's I and LISA, regions); the rest run from
// measuring one thing to optimising.
export const DEMO_CATEGORIES = [
  'Hypothesis testing',
  'Measurement',
  'Query and selection',
  'Transformation',
  'Optimisation',
] as const;

/** The cases grouped by category, in DEMO_CATEGORIES order, each group in catalogue order. A
 *  category with no case is left out; a case whose category is not listed goes last, under its
 *  own name, rather than disappearing. */
export function demosByCategory(cases: DemoCase[] = DEMOS): { category: string; cases: DemoCase[] }[] {
  const known: string[] = [...DEMO_CATEGORIES];
  const extra = [...new Set(cases.map((c) => c.category).filter((c) => !known.includes(c)))];
  return [...known, ...extra]
    .map((category) => ({ category, cases: cases.filter((c) => c.category === category) }))
    .filter((g) => g.cases.length > 0);
}

export function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${Math.round(n / 1024)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

export function demoBytes(c: DemoCase): number {
  return c.files.reduce((s, f) => s + f.bytes, 0);
}

/** The case's input files as File objects, fetched from where the page itself is served, so
 *  they go through the same upload path as a file the visitor attached by hand. */
export async function loadDemoFiles(c: DemoCase, base: string = import.meta.env.BASE_URL ?? '/'):
    Promise<File[]> {
  const root = base.endsWith('/') ? base : `${base}/`;
  return Promise.all(c.files.map(async (f) => {
    const r = await fetch(`${root}${f.path}`);
    if (!r.ok) throw new Error(`${f.name}: HTTP ${r.status}`);
    const blob = await r.blob();
    return new File([blob], f.name, { type: blob.type || 'application/octet-stream' });
  }));
}

/** The step to highlight: the first one not yet asked. */
export function nextStep(c: DemoCase, done: ReadonlySet<number>): number | null {
  const i = c.steps.findIndex((_, k) => !done.has(k));
  return i < 0 ? null : i;
}
